import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';

const Chat = () => {
  const location = useLocation();
  const { personality, gender } = location.state || {};  // '/settings'에서 전달된 값
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [error, setError] = useState(null);

  const handleSendMessage = async () => {
    try {
        const response = await fetch('http://127.0.0.1:8000/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                user_input: userMessage,
                personality: personality,
            }),
        });
        const data = await response.json();
        if (response.ok) {
            setMessages([...messages, { text: data.response, sender: 'bot' }]);
        } else {
            // 에러 메시지 처리
            throw new Error(data.detail || "Error fetching chatbot response");
        }
    } catch (error) {
        console.error("Error fetching chatbot response:", error);
        setMessages([...messages, { text: "오류가 발생했습니다. 욕설이 포함된 것 같아요.", sender: 'bot' }]);
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ user_input: userInput, personality, gender }),
      });

      if (!response.ok) {
        throw new Error("Failed to fetch response from the server");
      }

      const data = await response.json();
      const chatbotMessage = typeof data.response === "string"
        ? data.response
        : JSON.stringify(data.response);

      // 챗봇 응답을 chatHistory에 추가
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "chatbot", message: chatbotMessage },
      ]);
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError("챗봇 응답을 처리하는 중 오류가 발생했습니다.");  // 에러 상태 업데이트
    }

    // 사용자 입력 초기화
    setUserInput("");
  };

  return (
    <div>
      {error && <div style={{ color: "red" }}>{error}</div>}  {/* 에러 메시지 표시 */}
      <div>
        {chatHistory.map((chat, index) => (
          <div key={index} className={chat.sender}>
            <strong>{chat.sender === "user" ? "User" : "Chatbot"}:</strong> {chat.message}
          </div>
        ))}
      </div>
      <div>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
        />
        <button onClick={handleSendMessage}>전송</button>
      </div>
    </div>
  );
};

export default Chat;
